/**
 * The putter's real toolpath, generated by scripts/prep-toolpath.mjs from
 * assets-src/putter/putter-op1.nc (Haas TM-1P). Do not edit by hand.
 *
 * 5898 points (every 5th move of 29459), in the putter mesh's space.
 */
export const TOOLPATH_OPS: { name: string; tool: string; start: number }[] = [{"name":"Adaptive3","tool":"0.75 in flat end mill","start":0},{"name":"Bore2","tool":"0.25 in flat end mill","start":575},{"name":"Adaptive7","tool":"0.25 in flat end mill","start":591},{"name":"Steep and Shallow2","tool":"0.25 in ball end mill","start":1293}];

const PACKED = "";

/** x, y, z triples in mesh units. */
export function toolpath(): Float32Array {
  const bin = atob(PACKED);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const q = new Int16Array(bytes.buffer);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) out[i] = q[i]! / 50000;
  return out;
}
